insert into platform_modules(code,title,is_active) values ('41-documentation','مستندات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده مستندات','modules:41-documentation:read'),('write','ثبت و ویرایش سند','modules:41-documentation:write'),('delete','حذف سند','modules:41-documentation:delete'),('publish','فعال‌سازی سند','modules:41-documentation:publish'),('archive','بایگانی سند','modules:41-documentation:archive'),('ocr','ارسال برای OCR','modules:41-documentation:ocr'),('duplicate','تکثیر نسخه','modules:41-documentation:duplicate'),('version','ایجاد نسخه جدید','modules:41-documentation:version')) v(a,t,p) where m.code='41-documentation' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;