select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('document-code','کد سند','text',true,10,'{}'),('document-title','عنوان سند','text',true,20,'{}'),('document-type','نوع سند','select',true,30,'{"options":["دستورالعمل","آیین‌نامه","فرآیند","راهنما","خط‌مشی","قرارداد","گزارش","صورتجلسه","فرم","سایر"]}'),('file-reference','مرجع فایل','text',false,40,'{}'),('mime-type','نوع فایل','text',false,50,'{}'),('file-size','حجم فایل','number',false,60,'{}'),('document-date','تاریخ سند','text',false,70,'{}'),('owner','مالک سند','text',false,80,'{}'),('creator','ایجادکننده','text',false,90,'{}'),('version','نسخه','number',true,100,'{}'),('related-entity','موجودیت مرتبط','text',false,110,'{}'),('tags','برچسب‌ها','text',false,120,'{}'),('folder','پوشه','text',false,130,'{}'),('access-level','سطح دسترسی','select',true,140,'{"options":["عمومی","کاربران واردشده","نقش‌محور","سازمانی","محرمانه"]}'),('hash','Hash فایل','text',false,150,'{}'),('status','وضعیت','select',true,160,'{"options":["پیش‌نویس","فعال","نیازمند بازبینی","منسوخ","بایگانی شده"]}'),('ocr-status','وضعیت OCR','select',false,170,'{"options":["انجام نشده","در انتظار پردازش","پردازش شده","نیازمند بازبینی","ناموفق"]}'),('description','توضیحات','textarea',false,180,'{}'),('notes','یادداشت','textarea',false,190,'{}')
) v(k,t,ft,r,s,o) where m.code='41-documentation' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
